  private loginLimiter = new Map<string, TokenBucketRateLimiter>();

  public checkAllowed(req: RequestTelemetry): { allowed: boolean; reason?: string } {
    // Tier 1: Per-IP Check (100 req/sec)
    const ipBucket = this.getOrCreate(this.ipLimiter, req.clientIp, 100, 100);
    if (!ipBucket.allowRequest()) return { allowed: false, reason: "IP rate limit exceeded" };

    // Tier 2: Per-User Account Check (if authenticated, 50 req/sec)
    if (req.userId) {
      const userBucket = this.getOrCreate(this.userLimiter, req.userId, 50, 50);
      if (!userBucket.allowRequest()) return { allowed: false, reason: "User quota exceeded" };
    }

    // Tier 3: Sensitive Endpoint Check (/login: max 5 req/min)
    if (req.endpoint === "/api/login") {
      const loginKey = `${req.clientIp}_login`;
      const loginBucket = this.getOrCreate(this.loginLimiter, loginKey, 5, 5 / 60);
      if (!loginBucket.allowRequest()) return { allowed: false, reason: "Too many login attempts" };
    }

    return { allowed: true };
  }

  private getOrCreate(map: Map<string, TokenBucketRateLimiter>, key: string, cap: number, rate: number) {
    if (!map.has(key)) map.set(key, new TokenBucketRateLimiter(cap, rate));
    return map.get(key)!;
  }
}

enum CircuitState { CLOSED, OPEN, HALF_OPEN }

class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failureThreshold: number;
  private resetTimeoutMs: number;
  private failureCount: number = 0;
  private lastFailureTime: number = 0;

  constructor(failureThreshold: number = 3, resetTimeoutMs: number = 10000) {
    this.failureThreshold = failureThreshold;
    this.resetTimeoutMs = resetTimeoutMs;
  }

  public async execute<T>(action: () => Promise<T>): Promise<T> {
    const now = Date.now();

    // Check if OPEN breaker should transition to HALF_OPEN
    if (this.state === CircuitState.OPEN) {
      if (now - this.lastFailureTime > this.resetTimeoutMs) {
        console.log("[CircuitBreaker] Timeout elapsed. Entering HALF_OPEN state probe.");
        this.state = CircuitState.HALF_OPEN;
      } else {
        throw new Error("CircuitBreaker OPEN: Fast-failing downstream call!");
      }
    }

    try {
      const result = await action();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  private onSuccess(): void {
    if (this.state === CircuitState.HALF_OPEN) {
      console.log("[CircuitBreaker] Probe succeeded. Resetting to CLOSED state.");
      this.state = CircuitState.CLOSED;
      this.failureCount = 0;
    }
  }

  private onFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.state === CircuitState.HALF_OPEN || this.failureCount >= this.failureThreshold) {
      console.warn("[CircuitBreaker] Failure threshold reached! Tripping to OPEN state.");
      this.state = CircuitState.OPEN;
    }
  }
}

class BulkheadExecutor {
  private activeTasks: number = 0;
  private maxConcurrency: number;
  private queue: (() => void)[] = [];
  private maxQueue: number;

  constructor(maxConcurrency: number, maxQueue: number) {
    this.maxConcurrency = maxConcurrency;
    this.maxQueue = maxQueue;
  }

  public async run<T>(action: () => Promise<T>): Promise<T> {
    if (this.activeTasks >= this.maxConcurrency) {
      if (this.queue.length >= this.maxQueue) {
        throw new Error("Bulkhead saturated! Rejecting to protect host system.");
      }
      await new Promise(resolve => this.queue.push(resolve));
    }

    this.activeTasks++;
    try {
      return await action();
    } finally {
      this.activeTasks--;
      if (this.queue.length > 0) {
        const next = this.queue.shift()!;
        next();
      }
    }
  }
}

// Separate bulkheads per dependency:
const paymentBulkhead = new BulkheadExecutor(50, 100);
const analyticsBulkhead = new BulkheadExecutor(10, 20); // Analytics can NEVER consume payment threads!

class RetryWithJitter {
  public static async execute<T>(
    action: () => Promise<T>,
    maxRetries: number = 4,
    baseDelayMs: number = 200,
    maxDelayMs: number = 5000
  ): Promise<T> {
    let attempt = 0;

    while (true) {
      try {
        return await action();
      } catch (error) {
        attempt++;
        if (attempt > maxRetries) {
          throw new Error(`Operation failed after ${maxRetries} retries: ${error}`);
        }

        // Calculate Exponential Backoff ceiling: base * 2^attempt
        const expCeiling = Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt));

        // Full Jitter: Uniform random between 0 and expCeiling
        const sleepDuration = Math.random() * expCeiling;

        console.log(`[Retry] Attempt ${attempt} failed. Sleeping for ${Math.floor(sleepDuration)}ms...`);
        await new Promise(resolve => setTimeout(resolve, sleepDuration));
      }
    }
  }
}

class AdaptiveClientThrottler {
  private requests: number = 0;
  private accepts: number = 0;
  private kMultiplier: number; // Google SRE recommended K = 2.0 (allows 2x headroom)

  constructor(kMultiplier: number = 2.0) {
    this.kMultiplier = kMultiplier;
  }

  public shouldAllowClientRequest(): boolean {
    this.requests++;
    // Calculate client-side drop probability
    const dropProbability = Math.max(
      0,
      (this.requests - this.kMultiplier * this.accepts) / (this.requests + 1)
    );

    if (Math.random() < dropProbability) {
      console.warn("[AdaptiveThrottling] Dropped locally to protect overloaded backend!");
      return false; // Throttled client-side without network packet!
    }
    return true;
  }

  public recordResponse(isSuccess: boolean): void {
    if (isSuccess) this.accepts++;
  }
}

interface IdempotencyRecord {
  status: "PROCESSING" | "COMPLETED";
  response?: any;
  createdAt: number;
}

class IdempotencyEngine {
  private store: Map<string, IdempotencyRecord> = new Map();

  public async executeIdempotent<T>(
    idempotencyKey: string,
    action: () => Promise<T>
  ): Promise<T> {
    const existing = this.store.get(idempotencyKey);

    if (existing) {
      if (existing.status === "PROCESSING") {
        throw new Error("409 Conflict: Concurrent duplicate request in progress");
      }
      if (existing.status === "COMPLETED") {
        console.log(`[Idempotency] Returning cached response for key: ${idempotencyKey}`);
        return existing.response;
      }
    }

    // Mark as PROCESSING
    this.store.set(idempotencyKey, { status: "PROCESSING", createdAt: Date.now() });

    try {
      const result = await action();
      // Cache completed response
      this.store.set(idempotencyKey, {
        status: "COMPLETED",
        response: result,
        createdAt: Date.now()
      });
      return result;
    } catch (error) {
      this.store.delete(idempotencyKey); // Allow retry on fatal failure
      throw error;
    }
  }
}

class TicTacToeFast {
  private n: number;
  private rows: number[];
  private cols: number[];
  private diag: number = 0;
  private antiDiag: number = 0;

  constructor(n: number = 3) {
    this.n = n;
    this.rows = new Array(n).fill(0);
    this.cols = new Array(n).fill(0);
  }

  // Returns 0: No win, 1: Player 1 won, 2: Player 2 won
  public makeMove(row: number, col: number, player: 1 | 2): number {
    const value = player === 1 ? 1 : -1;

    this.rows[row] += value;
    this.cols[col] += value;

    if (row === col) this.diag += value;
    if (row + col === this.n - 1) this.antiDiag += value;

    const target = player === 1 ? this.n : -this.n;

    // Strict O(1) evaluation:
    if (
      this.rows[row] === target ||
      this.cols[col] === target ||
      this.diag === target ||
      this.antiDiag === target
    ) {
      return player; // Winning move!
    }
    return 0; // Game continues
  }
}

enum Color { WHITE, BLACK }

class Position {
  constructor(public readonly x: number, public readonly y: number) {}
}

abstract class Piece {
  constructor(public readonly color: Color) {}
  abstract canMove(from: Position, to: Position, board: ChessBoard): boolean;
}

class Knight extends Piece {
  canMove(from: Position, to: Position, board: ChessBoard): boolean {
    const dx = Math.abs(from.x - to.x);
    const dy = Math.abs(from.y - to.y);
    // Knight moves in L-shape: (2, 1) or (1, 2)
    const isLShape = (dx === 1 && dy === 2) || (dx === 2 && dy === 1);
    if (!isLShape) return false;

    const destPiece = board.getPiece(to);
    return destPiece === null || destPiece.color !== this.color;
  }
}

class ChessBoard {
  private grid: (Piece | null)[][] = Array.from({ length: 8 }, () => new Array(8).fill(null));

  public getPiece(pos: Position): Piece | null { return this.grid[pos.x][pos.y]; }
  public setPiece(pos: Position, piece: Piece | null): void { this.grid[pos.x][pos.y] = piece; }
}

class Jumper {
  constructor(public readonly start: number, public readonly end: number) {}
}

class SnakeAndLadderBoard {
  private jumpers: Map<number, number> = new Map();
  public readonly totalCells: number;

  constructor(size: number = 100, snakes: Jumper[], ladders: Jumper[]) {
    this.totalCells = size;
    for (const s of snakes) this.jumpers.set(s.start, s.end);
    for (const l of ladders) this.jumpers.set(l.start, l.end);
  }

  public getFinalPosition(targetCell: number): number {
    return this.jumpers.get(targetCell) ?? targetCell;
  }
}

class SnakeAndLadderGame {
  private playersQueue: { name: string; position: number }[] = [];
  private board: SnakeAndLadderBoard;

  constructor(board: SnakeAndLadderBoard, players: string[]) {
    this.board = board;
    this.playersQueue = players.map(name => ({ name, position: 0 }));
  }

  public playTurn(diceRoll: number): string {
    const player = this.playersQueue.shift()!;
    let nextPos = player.position + diceRoll;

    if (nextPos <= this.board.totalCells) {
      player.position = this.board.getFinalPosition(nextPos);
    }

    if (player.position === this.board.totalCells) {
      return `${player.name} wins the game!`;
    }

    this.playersQueue.push(player); // Re-enqueue for next round
    return `${player.name} moved to cell ${player.position}`;
  }
}

class ConnectFour {
  private rows = 6;
  private cols = 7;
  private grid: number[][] = Array.from({ length: 6 }, () => new Array(7).fill(0));

  public dropPiece(col: number, player: number): { row: number; col: number; won: boolean } {
    if (col < 0 || col >= this.cols || this.grid[0][col] !== 0) {
      throw new Error("Invalid column or column full!");
    }

    // Gravity: Find lowest unoccupied row
    let row = this.rows - 1;
    while (row >= 0 && this.grid[row][col] !== 0) row--;

    this.grid[row][col] = player;
    const won = this.checkWin(row, col, player);
    return { row, col, won };
  }

  private checkWin(r: number, c: number, player: number): boolean {
    const directions = [
      [0, 1],  // Horizontal
      [1, 0],  // Vertical
      [1, 1],  // Diagonal /
      [1, -1]  // Diagonal \
    ];

    for (const [dr, dc] of directions) {
      let count = 1;
      // Forward direction
      count += this.countStreak(r, c, dr, dc, player);
      // Backward direction
      count += this.countStreak(r, c, -dr, -dc, player);
      if (count >= 4) return true;
    }
    return false;
  }

  private countStreak(r: number, c: number, dr: number, dc: number, player: number): number {
    let streak = 0;
    let currR = r + dr, currC = c + dc;
    while (currR >= 0 && currR < this.rows && currC >= 0 && currC < this.cols && this.grid[currR][currC] === player) {
      streak++;
      currR += dr;
      currC += dc;
    }
    return streak;
  }
}

class Game2048Engine {
  // Core: slides non-zero numbers to left, merges adjacent equals once
  public static slideRowLeft(row: number[]): number[] {
    // 1. Filter out zeros (compact)
    let nonZero = row.filter(val => val !== 0);
    const result: number[] = [];

    // 2. Merge adjacent identical pairs
    for (let i = 0; i < nonZero.length; i++) {
      if (i < nonZero.length - 1 && nonZero[i] === nonZero[i + 1]) {
        result.push(nonZero[i] * 2);
        i++; // Skip merged sibling
      } else {
        result.push(nonZero[i]);
      }
    }

    // 3. Pad with trailing zeros to original length
    while (result.length < row.length) result.push(0);
    return result;
  }

  // Transpose matrix (swaps rows and columns)
  public static transpose(grid: number[][]): number[][] {
    return grid[0].map((_, colIndex) => grid.map(row => row[colIndex]));
  }
}

enum Suit { HEARTS, DIAMONDS, CLUBS, SPADES }
enum Rank { TWO = 2, THREE = 3, TEN = 10, JACK = 10, QUEEN = 10, KING = 10, ACE = 11 }

class Card {
  constructor(public readonly suit: Suit, public readonly rank: Rank) {}
}

class Deck {
  private cards: Card[] = [];

  constructor() { this.reset(); }

  public reset(): void {
    this.cards = [];
    for (const suit of [Suit.HEARTS, Suit.DIAMONDS, Suit.CLUBS, Suit.SPADES]) {
      for (const rank of [Rank.TWO, Rank.THREE, Rank.TEN, Rank.JACK, Rank.QUEEN, Rank.KING, Rank.ACE]) {
        this.cards.push(new Card(suit, rank));
      }
    }
  }

  // Unbiased Fisher-Yates Shuffle in O(N)
  public shuffle(): void {
    for (let i = this.cards.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [this.cards[i], this.cards[j]] = [this.cards[j], this.cards[i]];
    }
  }

  public deal(): Card | null { return this.cards.pop() ?? null; }
}

class BlackjackHand {
  private cards: Card[] = [];

  public addCard(c: Card) { this.cards.push(c); }

  public getScore(): number {
    let score = this.cards.reduce((sum, c) => sum + c.rank, 0);
    let aces = this.cards.filter(c => c.rank === Rank.ACE).length;

    // Downgrade Aces from 11 to 1 if busted!
    while (score > 21 && aces > 0) {
      score -= 10;
      aces--;
    }
    return score;
  }
}

